sp_widget.css:
.content-card {
  background: #fff;
  border-radius: 16px;
  padding: 24px;
  box-shadow: 0 2px 12px rgba(0,0,0,0.07);
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 20px;
  padding-bottom: 14px;
  border-bottom: 2px solid #f1f5f9;
}

.card-header h3 {
  margin: 0;
  font-size: 16px;
  font-weight: 700;
  color: #1a2332;
  display: flex;
  align-items: center;
  gap: 8px;
}

.card-header h3 i {
  color: #1a73e8;
}

.view-all-link {
  font-size: 13px;
  font-weight: 500;
  color: #1a73e8;
  text-decoration: none;
}

.view-all-link:hover {
  text-decoration: underline;
}

.trackmed-table {
  width: 100%;
  border-collapse: collapse;
}

.trackmed-table thead tr {
  background: #f8fafc;
}

.trackmed-table th {
  padding: 10px 14px;
  text-align: left;
  font-size: 12px;
  text-transform: uppercase;
  color: #64748b;
  letter-spacing: .5px;
  border-bottom: 1px solid #e2e8f0;
}

.trackmed-table td {
  padding: 12px 14px;
  border-bottom: 1px solid #f1f5f9;
  color: #374151;
  font-size: 14px;
}

.trackmed-table tr:last-child td {
  border-bottom: none;
}

.trackmed-table tr:hover td {
  background: #f8fafc;
}

.patient-cell {
  display: flex;
  align-items: center;
  gap: 10px;
}

.avatar-circle {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: linear-gradient(
      135deg,
      #1a73e8,
      #06b6d4
  );

  color: #fff;
  font-size: 12px;
  font-weight: 700;

  display: flex;
  justify-content: center;
  align-items: center;
}

.med-name {
  color: #475569;
}

.time-cell {
  display: flex;
  align-items: center;
  gap: 5px;
  color: #64748b;
}

.status-pill {
  padding: 4px 12px;
  border-radius: 20px;
  font-size: 12px;
  font-weight: 600;
}

.status-pending {
  background: #fef3c7;
  color: #d97706;
}

.status-completed {
  background: #dcfce7;
  color: #16a34a;
}

.status-missed {
  background: #fee2e2;
  color: #dc2626;
}

